/* Reset routines */

void MOD_mkTbFormat::reset_RST_N(tUInt8 ARG_rst_in)
{
  PORT_RST_N = ARG_rst_in;
  INST_ver.reset_RST(ARG_rst_in);
  INST_phase.reset_RST(ARG_rst_in);
  INST_gd.reset_RST(ARG_rst_in);
  INST_gc.reset_RST(ARG_rst_in);
  INST_gb.reset_RST(ARG_rst_in);
  INST_ga.reset_RST(ARG_rst_in);
  INST_cnt.reset_RST(ARG_rst_in);
}


