/* Functions to set the elaborated clock id */

void MOD_mkTbFormat::set_clk_0(char const *s)
{
  __clk_handle_0 = bk_get_or_define_clock(sim_hdl, s);
}


/* State dumping routine */
void MOD_mkTbFormat::dump_state(unsigned int indent)
{
  printf("%*s%s:\n", indent, "", inst_name);
  INST_cnt.dump_state(indent + 2u);
  INST_ga.dump_state(indent + 2u);
  INST_gb.dump_state(indent + 2u);
  INST_gc.dump_state(indent + 2u);
  INST_gd.dump_state(indent + 2u);
  INST_phase.dump_state(indent + 2u);
  INST_ver.dump_state(indent + 2u);
}


/* VCD dumping routines */

unsigned int MOD_mkTbFormat::dump_VCD_defs(unsigned int levels)
{
  vcd_write_scope_start(sim_hdl, inst_name);
  vcd_num = vcd_reserve_ids(sim_hdl, 10u);
  unsigned int num = vcd_num;
  for (unsigned int clk = 0u; clk < bk_num_clocks(sim_hdl); ++clk)
    vcd_add_clock_def(sim_hdl, this, bk_clock_name(sim_hdl, clk), bk_clock_vcd_num(sim_hdl, clk));
  vcd_write_def(sim_hdl, bk_clock_vcd_num(sim_hdl, __clk_handle_0), "CLK", 1u);
  vcd_write_def(sim_hdl, num++, "RST_N", 1u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "b__h320", 32u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "cnt_PLUS_1___d902", 32u);
  num = INST_cnt.dump_VCD_defs(num);
  num = INST_ga.dump_VCD_defs(num);
  num = INST_gb.dump_VCD_defs(num);
  num = INST_gc.dump_VCD_defs(num);
  num = INST_gd.dump_VCD_defs(num);
  num = INST_phase.dump_VCD_defs(num);
  num = INST_ver.dump_VCD_defs(num);
  vcd_write_scope_end(sim_hdl);
  return num;
}

void MOD_mkTbFormat::dump_VCD(tVCDDumpType dt, unsigned int levels, MOD_mkTbFormat &backing)
{
  vcd_defs(dt, backing);
  vcd_prims(dt, backing);
}

void MOD_mkTbFormat::vcd_defs(tVCDDumpType dt, MOD_mkTbFormat &backing)
{
  unsigned int num = vcd_num;
  if (dt == VCD_DUMP_XS)
  {
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 32u);
    vcd_write_x(sim_hdl, num++, 32u);
  }
  else
    if (dt == VCD_DUMP_CHANGES)
    {
      if ((backing.PORT_RST_N) != PORT_RST_N)
      {
	vcd_write_val(sim_hdl, num, PORT_RST_N, 1u);
	backing.PORT_RST_N = PORT_RST_N;
      }
      ++num;
      if ((backing.DEF_b__h320) != DEF_b__h320)
      {
	vcd_write_val(sim_hdl, num, DEF_b__h320, 32u);
	backing.DEF_b__h320 = DEF_b__h320;
      }
      ++num;
      if ((backing.DEF_cnt_PLUS_1___d902) != DEF_cnt_PLUS_1___d902)
      {
	vcd_write_val(sim_hdl, num, DEF_cnt_PLUS_1___d902, 32u);
	backing.DEF_cnt_PLUS_1___d902 = DEF_cnt_PLUS_1___d902;
      }
      ++num;
    }
    else
    {
      vcd_write_val(sim_hdl, num++, PORT_RST_N, 1u);
      backing.PORT_RST_N = PORT_RST_N;
      vcd_write_val(sim_hdl, num++, DEF_b__h320, 32u);
      backing.DEF_b__h320 = DEF_b__h320;
      vcd_write_val(sim_hdl, num++, DEF_cnt_PLUS_1___d902, 32u);
      backing.DEF_cnt_PLUS_1___d902 = DEF_cnt_PLUS_1___d902;
    }
}

void MOD_mkTbFormat::vcd_prims(tVCDDumpType dt, MOD_mkTbFormat &backing)
{
  INST_cnt.dump_VCD(dt, backing.INST_cnt);
  INST_ga.dump_VCD(dt, backing.INST_ga);
  INST_gb.dump_VCD(dt, backing.INST_gb);
  INST_gc.dump_VCD(dt, backing.INST_gc);
  INST_gd.dump_VCD(dt, backing.INST_gd);
  INST_phase.dump_VCD(dt, backing.INST_phase);
  INST_ver.dump_VCD(dt, backing.INST_ver);
}
